from itertools import product, permutations

def subseq_set(S,M):
    res=set()
    n=len(S)
    def gen(idx, cur):
        if len(cur)==M:
            res.add(tuple(cur)); return
        if idx==n: return
        gen(idx+1, cur)
        cur.append(S[idx]); gen(idx+1, cur); cur.pop()
    gen(0, [])
    return res

def check_property(S,X,K,M):
    sub=subseq_set(S,M)
    xt=tuple(X)
    if xt in sub: return False
    for Y in product(range(1,K+1), repeat=M):
        if Y==xt: continue
        if Y not in sub: return False
    return True

def count_valid(N,M,K,X):
    cnt=0
    for S in product(range(1,K+1), repeat=N):
        if check_property(list(S), X,K,M):
            cnt+=1
    return cnt

def brute_classify(K,M):
    N=M*K-1
    print(f"Classify K={K} M={M} Nmin={N}")
    for X in product(range(1,K+1), repeat=M):
        cnt=count_valid(N,M,K,list(X))
        print(X,cnt)

def brute_next(N,M,K):
    print(f"Brute N={N} M={M} K={K}")
    for X in product(range(1,K+1), repeat=M):
        cnt=count_valid(N,M,K,list(X))
        if cnt>0:
            print(f" X={X} cnt={cnt}")

